T={'1':np.ones_like(t),'1/t':1/t,'t':t,'e-t':np.exp(-t),'t2':t**2,'1/t2':1/t**2,'lnt':np.log(t),'e-2t':np.exp(-2*t)}
Aa={'1':np.ones_like(A),'A':A,'A2':A**2,'A3':A**3,'1/A':1/A,'lnA':np.log(A)}
def fit(tk,ak):
    cols=[];names=[]
    for a in ak:
        for tt in tk:
            cols.append(T[tt]*Aa[a]);names.append(tt+'*'+a)
    M=np.c_[tuple(cols)]
    c,*_=np.linalg.lstsq(M,dA_dt,rcond=None)
    r=dA_dt-M@c
    return np.mean(r**2)/np.var(dA_dt),names,c
